 "content": "def transform(grid):
    """Stamp the shape formed by the special-color cells onto matching zero cells."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 5)}
    if not colors:
        return [row[:] for row in grid]
    marker = next(iter(colors))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    min_r = min(r for r, _ in points)
    min_c = min(c for _, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    sh = max(r for r, _ in shape) + 1
    sw = max(c for _, c in shape) + 1
    out = [row[:] for row in grid]
    for r0 in range(h - sh + 1):
        for c0 in range(w - sw + 1):
            cells = [(r0 + dr, c0 + dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = marker
    return out
